class INonBlockingReader(object):
    """Interface for readers that do not block a thread while waiting for output from stream"""

    def has_line_without_blocking(self):
        """
        If next line is ready to read without blocking.
        :return: bool
        """
        return False

    def read_lines(self):
        """
        Reads lines ot throw exception.
        :return: [string]
        """
        return ""

    def is_finish(self):
        """
        Is EOF reached.
        :return:
        """
        return True

    def close(self):
        """Sends Ctrl-C or terminates cmd by kill cmd"""
        pass
